# One-off script: adds cross-field pharmaceutical AI projects (EN + AR) and assigns fields.
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
EN = os.path.join(ROOT, 'content/projects'); AR = os.path.join(ROOT, 'content/ar/projects')

# field keys follow the medicine's life: rd, manufacturing, regulatory, supply, commercial, hospital, community, safety
existing = {
  'pharmacy-inventory-prediction': ('community', 1),
  'patient-support': ('community', 2),
  'medication-safety': ('hospital', 1),
  'drug-interaction-intelligence': ('hospital', 2),
  'clinical-workflow-automation': ('hospital', 3),
}
ORDER = ['rd', 'manufacturing', 'regulatory', 'supply', 'commercial', 'hospital', 'community', 'safety']
for slug, (field, k) in existing.items():
    f = os.path.join(EN, slug + '.json'); d = json.load(open(f)); d['field'] = field; d['order'] = ORDER.index(field) * 10 + k
    if slug == 'clinical-workflow-automation': d['area'] = 'Clinical Workflow Automation'
    json.dump(d, open(f, 'w'), indent=2, ensure_ascii=False)

def P(slug, field, k, en, ar, refs=()):
    base = dict(slug=slug, field=field, order=ORDER.index(field) * 10 + k, phase=en.pop('phase', 2), status='Conceptual',
                references=[{'title': t, 'url': u} for t, u in refs], screenshots=[], video='', seoTitle='', seoDescription='')
    base.update(en); json.dump(base, open(os.path.join(EN, slug + '.json'), 'w'), indent=2, ensure_ascii=False)
    json.dump({'slug': slug, **ar}, open(os.path.join(AR, slug + '.json'), 'w'), indent=2, ensure_ascii=False)

